// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.connectivity.sosimport android.content.BroadcastReceiverimport android.content.Contextimport android.content.Intentimport timber.log.Timberimport java.util.ArrayDequeimport java.util.concurrent.atomic.AtomicReference/** * NOUS — SOS Power-Tap Receiver (Module 11 v3 — P1). * * Strategy §"EmergencySOSEngine": "5-tap power button within 2 seconds → trigger SOS". * * Listens for `ACTION_SCREEN_ON` / `ACTION_SCREEN_OFF` system broadcasts * (which fire when the user presses the power button). Counts taps within * a 2-second window; if 5 taps accumulate, fires the [onFiveTaps] callback * which triggers the SOS sequence. * * ## Why this is a BroadcastReceiver, not a Service * * The system broadcasts SCREEN_ON/SCREEN_OFF to any registered receiver — * no special permission needed. A foreground service would waste battery * for what is a 5-tap-in-2s pattern check. * * ## Registration lifecycle * * The receiver must be registered dynamically (via `Context.registerReceiver`) * — static manifest receivers cannot receive SCREEN_ON/OFF (Android security * restriction since 9.0). [com.roshan.persona.connectivity.di.ConnectivityModule] * registers it at app startup; the SOS engine holds the listener ref. * * @see <a href="docs/strategy/module-11-connectivity-strategy-v3.md">§EmergencySOSEngine</a> */class SosPowerTapReceiver(    private val onFiveTaps: () -> Unit,) : BroadcastReceiver() {    /** Timestamps of recent screen on/off events (most-recent last). */    private val taps = ArrayDeque<Long>()    private val lock = Any()    /** Set by the engine when the SOS is already dispatching — avoid double-trigger. */    private val armed = AtomicReference(true)    override fun onReceive(context: Context?, intent: Intent?) {        val action = intent?.action ?: return        if (action != Intent.ACTION_SCREEN_ON && action != Intent.ACTION_SCREEN_OFF) return        val now = System.currentTimeMillis()        val windowMs = TAP_WINDOW_MS        synchronized(lock) {            // Drop taps older than the window.            while (taps.isNotEmpty() && (now - (taps.peekFirst() ?: 0)) > windowMs) {                taps.pollFirst()            }            taps.addLast(now)            val count = taps.size            Timber.tag(TAG).d("Power tap registered (count=$count, action=$action).")            if (count >= REQUIRED_TAPS && armed.get()) {                // Reset so we don't fire again until the user re-triggers.                taps.clear()                armed.set(false)                Timber.tag(TAG).w("5-tap SOS pattern detected — firing onFiveTaps callback!")                try {                    onFiveTaps()                } catch (t: Throwable) {                    Timber.tag(TAG).e(t, "onFiveTaps callback threw")                }                // Re-arm after a cooldown to allow subsequent triggers.                Thread.sleep(REARM_COOLDOWN_MS)                armed.set(true)            }        }    }    /** Manually re-arm (called by the engine after the SOS sequence completes/cancels). */    fun rearm() {        armed.set(true)        synchronized(lock) { taps.clear() }    }    private companion object {        private const val TAG = "SosPowerTap"        private const val REQUIRED_TAPS = 5        private const val TAP_WINDOW_MS = 2000L        private const val REARM_COOLDOWN_MS = 5000L    }}